    local ok, id = --[[APR_DIAG]]
        APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](GetChannelName, self.name)
    if ok and ValidID(id) then
        if self.owned then self.ownedConfirmed = true end
        return id
    end
